/* ===================== BÀI 15 · Bit, byte, nibble, word, KiB/MiB và KB/MB ===================== */
/* Bài 15 · Bit, byte, nibble, word, KiB/MiB và KB/MB (CM02.01) — sinh bởi tools/author/maytinh/m15.py, không sửa tay.
   Phòng mô phỏng từng bước và bài tập chấm tự động; phần chữ bài học ở lesson.html (nội dung bảo vệ). */
makeMtLab(document.getElementById("lab-l15"),{id:"l15",scenarios:[{"label": "Ví dụ: Số tổ hợp của bit, nibble, byte", "note": "Mỗi bit thêm vào nhân đôi số tổ hợp.", "steps": [{"t": "1 bit: 2 giá trị", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số bit<\/th><th scope=\"col\">Số tổ hợp<\/th><th scope=\"col\">Ví dụ<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>2<\/td><td>0, 1<\/td><\/tr><\/tbody><\/table>", "say": "<p>Bit là một chữ số nhị phân. Mỗi bit thêm vào nhân đôi số tổ hợp.<\/p>"}, {"t": "4 bit (nibble): 16 tổ hợp", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số bit<\/th><th scope=\"col\">Số tổ hợp<\/th><th scope=\"col\">Ví dụ<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>2<\/td><td>0, 1<\/td><\/tr><tr><td>4<\/td><td class=\"new\">16<\/td><td>nibble<\/td><\/tr><\/tbody><\/table>"}, {"t": "8 bit (byte): 256 tổ hợp", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số bit<\/th><th scope=\"col\">Số tổ hợp<\/th><th scope=\"col\">Ví dụ<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>2<\/td><td>0, 1<\/td><\/tr><tr><td>4<\/td><td>16<\/td><td>nibble<\/td><\/tr><tr><td>8<\/td><td class=\"new\">256<\/td><td>byte<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Một byte (8 bit) có bao nhiêu tổ hợp khác nhau?", "o": ["8", "256", "255"], "a": 1}}, {"t": "16 bit (16 bit): 65 536 tổ hợp", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số bit<\/th><th scope=\"col\">Số tổ hợp<\/th><th scope=\"col\">Ví dụ<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>2<\/td><td>0, 1<\/td><\/tr><tr><td>4<\/td><td>16<\/td><td>nibble<\/td><\/tr><tr><td>8<\/td><td>256<\/td><td>byte<\/td><\/tr><tr><td>16<\/td><td class=\"new\">65 536<\/td><td>16 bit<\/td><\/tr><\/tbody><\/table>"}, {"t": "32 bit (32 bit): 4 294 967 296 tổ hợp", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số bit<\/th><th scope=\"col\">Số tổ hợp<\/th><th scope=\"col\">Ví dụ<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>2<\/td><td>0, 1<\/td><\/tr><tr><td>4<\/td><td>16<\/td><td>nibble<\/td><\/tr><tr><td>8<\/td><td>256<\/td><td>byte<\/td><\/tr><tr><td>16<\/td><td>65 536<\/td><td>16 bit<\/td><\/tr><tr><td>32<\/td><td class=\"new\">4 294 967 296<\/td><td>32 bit<\/td><\/tr><\/tbody><\/table>", "say": "<p>4 bit gọi là nibble, đúng bằng một chữ số hệ 16 (Bài 16). 8 bit là byte, đơn vị nhỏ nhất có địa chỉ riêng trong bộ nhớ của hầu hết máy tính.<\/p>"}]}, {"label": "Ví dụ: Tiền tố thập phân và nhị phân", "note": "Chênh lệch tăng dần từ 2,4% (Ki) tới gần 10% (Ti).", "steps": [{"t": "Hai họ tiền tố", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Thập phân (SI)<\/th><th scope=\"col\">Giá trị<\/th><th scope=\"col\">Nhị phân (IEC)<\/th><th scope=\"col\">Giá trị<\/th><\/tr><\/thead><tbody><tr><td>kB<\/td><td>10³ = 1 000<\/td><td>KiB<\/td><td>2¹⁰ = 1 024<\/td><\/tr><tr><td>MB<\/td><td>10⁶<\/td><td>MiB<\/td><td>2²⁰ = 1 048 576<\/td><\/tr><tr><td>GB<\/td><td>10⁹<\/td><td>GiB<\/td><td>2³⁰ = 1 073 741 824<\/td><\/tr><tr><td>TB<\/td><td>10¹²<\/td><td>TiB<\/td><td>2⁴⁰ ≈ 1,0995 × 10¹²<\/td><\/tr><\/tbody><\/table>", "say": "<p>Năm 1998, IEC đưa ra tiền tố nhị phân KiB, MiB, GiB để phân biệt với kB, MB, GB theo hệ SI. Nhiều phần mềm vẫn viết “KB, MB, GB” cho giá trị nhị phân.<\/p>"}, {"t": "Chênh lệch tăng theo cấp", "html": "<div class=\"mt-bars\"><div><span>Ki/k<\/span><span><i class=\"\" style=\"width:24.1%\"><\/i><em>2,4%<\/em><\/span><\/div><div><span>Mi/M<\/span><span><i class=\"w\" style=\"width:48.8%\"><\/i><em>4,9%<\/em><\/span><\/div><div><span>Gi/G<\/span><span><i class=\"w\" style=\"width:74.1%\"><\/i><em>7,4%<\/em><\/span><\/div><div><span>Ti/T<\/span><span><i class=\"e\" style=\"width:100.0%\"><\/i><em>10,0%<\/em><\/span><\/div><\/div><p class=\"mt-cap\">Tỉ lệ (2¹⁰ⁿ − 10³ⁿ) ÷ 10³ⁿ<\/p>", "ask": {"q": "1 GiB lớn hơn 1 GB khoảng bao nhiêu phần trăm?", "o": ["2,4%", "7,4%", "24%"], "a": 1}}]}, {"label": "Ví dụ: Ổ 1 TB hiện 931 GB", "note": "Cùng số byte, khác cách gọi đơn vị.", "steps": [{"t": "Ổ cứng ghi 1 TB = 10¹² byte", "html": "<p class=\"mt-calc\">Nhà sản xuất ổ đĩa dùng tiền tố thập phân: 1 TB = 1 000 000 000 000 byte<\/p>", "say": "<p>Mua ổ “1 TB”, cắm vào Windows lại thấy khoảng 931 “GB”. Có bị thiếu không?<\/p>"}, {"t": "Windows chia cho 2³⁰ nhưng vẫn ghi “GB”", "html": "<p class=\"mt-calc\">10¹² ÷ 1 073 741 824 ≈ <b>931,32<\/b> → hiện “931 GB” (thật ra là GiB)<\/p>", "ask": {"q": "10¹² byte bằng khoảng bao nhiêu GiB?", "o": ["1 000", "Khoảng 931", "1 024"], "a": 1}}, {"t": "Không thiếu byte nào", "html": "<p class=\"mt-calc\">Cùng một số byte, hai cách gọi đơn vị. Ngoài ra hệ thống tệp còn dùng một phần cho siêu dữ liệu (Chương 10)<\/p>", "say": "<p>Nên ghi rõ đơn vị khi báo cáo: “931 GiB” hoặc “1 000 GB”.<\/p>"}]}, {"label": "Ví dụ: Mạng 100 Mbit/s tải nhanh cỡ nào", "note": "Đổi bit sang byte rồi tính thời gian.", "steps": [{"t": "Gói cước mạng 100 Mbit/s", "html": "<p class=\"mt-calc\">Tốc độ đường truyền tính bằng <b>bit<\/b> mỗi giây, tiền tố thập phân: 100 Mbit/s = 10⁸ bit/s<\/p>", "say": "<p>Ký hiệu thường gặp: Mbps, Mb/s, Mbit/s đều là megabit mỗi giây.<\/p>"}, {"t": "Đổi sang byte: chia 8 → 12,5 MB/s", "html": "<p class=\"mt-calc\">10⁸ ÷ 8 = 1,25 × 10⁷ byte/s = <b>12,5 MB/s<\/b><\/p>", "ask": {"q": "100 Mbit/s tương đương tối đa bao nhiêu MB/s?", "o": ["100 MB/s", "12,5 MB/s", "800 MB/s"], "a": 1}}, {"t": "Tải tệp 1 GB mất tối thiểu 80 giây", "html": "<p class=\"mt-calc\">8 × 10⁹ bit ÷ 10⁸ bit/s = <b>80 s<\/b> (lý thuyết; thực tế lâu hơn vì phần đầu gói tin, giao thức, mạng chia sẻ)<\/p>", "say": "<p>Băng thông lý thuyết và tốc độ thực tế khác nhau; Chương 11 và Chương 17 sẽ đo phần chênh lệch này.<\/p>"}]}, {"label": "Ví dụ: RAM 16 GB là bao nhiêu byte", "note": "RAM dùng nghĩa nhị phân của GB.", "steps": [{"t": "Thanh RAM “16 GB”", "html": "<p class=\"mt-calc\">Dung lượng chip nhớ là lũy thừa của 2: 16 GB RAM thực chất là 16 × 2³⁰ = 17 179 869 184 byte = 16 GiB<\/p>", "say": "<p>Cùng chữ “GB”: ổ đĩa dùng nghĩa thập phân, RAM dùng nghĩa nhị phân.<\/p>"}, {"t": "Windows báo “Usable” ít hơn 16", "html": "<p class=\"mt-calc\">Một phần RAM có thể dành cho đồ họa tích hợp hoặc phần cứng khác; con số cụ thể tùy máy (Chương 7)<\/p>", "ask": {"q": "Thanh RAM “16 GB” chứa bao nhiêu byte?", "o": ["16 000 000 000", "17 179 869 184", "16 384"], "a": 1}, "say": "<p>16 × 1 073 741 824 = 17 179 869 184 byte.<\/p>"}]}, {"label": "Bẫy: “Word” dài bao nhiêu?", "note": "Word phụ thuộc kiến trúc và tài liệu.", "steps": [{"t": "“Word” không có một độ dài cố định", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Ngữ cảnh<\/th><th scope=\"col\">Word nghĩa là<\/th><\/tr><\/thead><tbody><tr><td>Tài liệu Intel x86 (WORD, DWORD, QWORD)<\/td><td>16, 32, 64 bit<\/td><\/tr><tr><td>CPU 64 bit nói chung<\/td><td>thường là 64 bit (độ rộng thanh ghi)<\/td><\/tr><tr><td>Bộ xử lý 8 bit (Bài 5)<\/td><td>có thể là 8 hoặc 16 bit tùy tài liệu<\/td><\/tr><\/tbody><\/table>", "say": "<p>Word là đơn vị dữ liệu “tự nhiên” của một kiến trúc. Khi đọc tài liệu phải xem nó định nghĩa word là bao nhiêu bit.<\/p>"}, {"t": "Ví dụ: “ghi một WORD” trong tài liệu x86", "html": "<p class=\"mt-calc\">WORD = 2 byte · DWORD (double word) = 4 byte · QWORD (quad word) = 8 byte<\/p>", "ask": {"q": "Trong thuật ngữ của tài liệu x86, một DWORD dài bao nhiêu byte?", "o": ["2", "4", "8"], "a": 1}}, {"t": "Sửa: luôn ghi số bit", "html": "<p class=\"mt-calc\">Viết “thanh ghi 16 bit”, “số nguyên 32 bit” thay vì “một word”<\/p>", "say": "<p>Thiết bị công nghiệp cũng vậy: thanh ghi Modbus là 16 bit, nhưng giá trị 32 bit chiếm hai thanh ghi (Bài 20).<\/p>"}]}, {"label": "Lỗi: Nhầm Mb với MB", "note": "b thường là bit, B hoa là byte.", "steps": [{"t": "Máy chép tệp 400 Mb trong 1 giây?", "html": "<p class=\"mt-calc\">Báo cáo ghi “ổ đĩa đạt 400 Mb/s” nhưng ý định là megabyte<\/p>", "say": "<p>b thường (bit) và B hoa (byte) chênh nhau 8 lần.<\/p>"}, {"t": "400 Mb/s chỉ là 50 MB/s", "html": "<p class=\"mt-calc\">400 ÷ 8 = <b>50 MB/s<\/b><\/p><div class=\"mt-bars\"><div><span>400 MB/s (ý định)<\/span><span><i class=\"o\" style=\"width:100.0%\"><\/i><em>400 MB/s<\/em><\/span><\/div><div><span>400 Mb/s (đã viết)<\/span><span><i class=\"e\" style=\"width:12.5%\"><\/i><em>50 MB/s<\/em><\/span><\/div><\/div>", "ask": {"q": "400 Mb/s bằng bao nhiêu MB/s?", "o": ["400", "3 200", "50"], "a": 2}}, {"t": "Sửa: viết đơn vị đầy đủ", "html": "<p class=\"mt-calc\">Dùng “Mbit/s” và “MB/s” (hoặc “MiB/s”), không viết tắt mơ hồ<\/p>", "say": "<p>Quy ước: tốc độ mạng và đường truyền nối tiếp thường tính bằng bit/s; dung lượng tệp, bộ nhớ, tốc độ ổ đĩa thường tính bằng byte.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l15"),"l15",[{"kind": "num", "t": "Đổi đơn vị dung lượng", "d": "<p>Ghi số byte (số nguyên) hoặc số thập phân làm tròn 2 chữ số.<\/p>", "items": [{"q": "3 KiB = ? byte", "a": 3072}, {"q": "2 MB (thập phân) = ? byte", "a": 2000000}, {"q": "1 GiB = ? byte", "a": 1073741824}, {"q": "Ổ 500 GB (thập phân) bằng bao nhiêu GiB?", "a": 465.66128730773926, "tol": 0.01, "unit": "GiB"}], "hints": ["KiB = 1 024 byte; MB = 1 000 000 byte.", "1 GiB = 2³⁰ = 1 073 741 824 byte.", "500 × 10⁹ ÷ 2³⁰."], "why": "3 × 1 024 = 3 072; 2 × 10⁶; 2³⁰ = 1 073 741 824; 5 × 10¹¹ ÷ 2³⁰ ≈ 465,66 GiB."}, {"kind": "num", "t": "Tốc độ và thời gian truyền", "d": "<p>Bỏ qua mọi chi phí giao thức. Làm tròn 2 chữ số thập phân.<\/p>", "items": [{"q": "50 Mbit/s = ? MB/s", "a": 6.25, "tol": 0.01, "unit": "MB/s"}, {"q": "1 Gbit/s = ? MB/s", "a": 125, "tol": 0.01, "unit": "MB/s"}, {"q": "Tệp 4 GB (thập phân) qua 1 Gbit/s mất tối thiểu?", "a": 32, "tol": 0.01, "unit": "giây"}, {"q": "Tệp 25 MB qua 10 Mbit/s mất tối thiểu?", "a": 20, "tol": 0.01, "unit": "giây"}], "hints": ["Chia số bit/s cho 8 để ra byte/s.", "Thời gian = (dung lượng × 8) ÷ tốc độ bit.", "4 GB = 3,2 × 10¹⁰ bit."], "why": "50 ÷ 8 = 6,25; 1 000 ÷ 8 = 125; 3,2 × 10¹⁰ ÷ 10⁹ = 32 s; 2 × 10⁸ bit ÷ 10⁷ = 20 s."}, {"kind": "num", "t": "Bit và tổ hợp", "d": "<p>Trả lời bằng số nguyên.<\/p>", "items": [{"q": "Bao nhiêu bit trong một nibble?", "a": 4}, {"q": "Cần ít nhất bao nhiêu bit để đánh số 1 000 cảm biến khác nhau?", "a": 10}, {"q": "Một QWORD (tài liệu x86) có bao nhiêu bit?", "a": 64}, {"q": "12 bit có bao nhiêu tổ hợp?", "a": 4096}], "hints": ["n bit đủ cho tối đa 2ⁿ giá trị.", "2⁹ = 512 < 1 000 ≤ 2¹⁰ = 1 024.", "WORD 16, DWORD 32, QWORD 64."], "why": "Nibble 4 bit; 1 000 giá trị cần 10 bit (2¹⁰ = 1 024); QWORD 64 bit; 2¹² = 4 096."}]);

makeQuiz("quiz15","score15",[{"q": "1 KiB bằng bao nhiêu byte?", "o": ["1 000", "1 024", "8 192", "1 048 576"], "a": 1, "e": "KiB là tiền tố nhị phân: 2¹⁰ = 1 024 byte. 1 000 byte là 1 kB."}, {"q": "Vì sao ổ cứng 1 TB hiện khoảng 931 GB trong Windows?", "o": ["Ổ bị lỗi", "Windows chiếm 69 GB", "Nhà sản xuất làm tròn sai", "Windows chia cho 2³⁰ nhưng vẫn ghi đơn vị là GB"], "a": 3, "e": "10¹² ÷ 2³⁰ ≈ 931,3. Đúng tên đơn vị phải là GiB."}, {"q": "Đường truyền 200 Mbit/s tương đương tối đa bao nhiêu MB/s?", "o": ["25", "200", "1 600", "20"], "a": 0, "e": "200 ÷ 8 = 25 MB/s (bỏ qua chi phí giao thức)."}, {"q": "Câu nào đúng về “word”?", "o": ["Luôn là 16 bit", "Luôn là 32 bit", "Độ dài phụ thuộc kiến trúc và tài liệu", "Luôn bằng 1 byte"], "a": 2, "e": "Tài liệu x86 gọi WORD = 16 bit vì lý do lịch sử; CPU 64 bit có word tự nhiên 64 bit. Hãy ghi rõ số bit."}, {"q": "Cần ít nhất bao nhiêu bit để biểu diễn 300 giá trị khác nhau?", "o": ["8", "9", "300", "10"], "a": 1, "e": "2⁸ = 256 < 300 ≤ 2⁹ = 512, nên cần 9 bit."}]);

